<?php
function material_upload(array $file,string $folder='materials'):?string{if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||($file['size']??0)>10485760||!is_uploaded_file($file['tmp_name']))return null;$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($types[$mime]))return null;$dir=__DIR__.'/../uploads/'.$folder;if(!is_dir($dir)&&!mkdir($dir,0755,true))return null;$name=bin2hex(random_bytes(16)).'.'.$types[$mime];return move_uploaded_file($file['tmp_name'],$dir.'/'.$name)?'/Prime-2/uploads/'.$folder.'/'.$name:null;}
function average_hex(string $file):string{$raw=@file_get_contents($file);$source=$raw?@imagecreatefromstring($raw):false;if(!$source)return '#808080';$small=imagecreatetruecolor(40,40);imagealphablending($small,true);$white=imagecolorallocate($small,255,255,255);imagefill($small,0,0,$white);imagecopyresampled($small,$source,0,0,0,0,40,40,imagesx($source),imagesy($source));$r=$g=$b=0;for($x=0;$x<40;$x++)for($y=0;$y<40;$y++){$rgb=imagecolorat($small,$x,$y);$r+=($rgb>>16)&255;$g+=($rgb>>8)&255;$b+=$rgb&255;}imagedestroy($source);imagedestroy($small);return sprintf('#%02X%02X%02X',round($r/1600),round($g/1600),round($b/1600));}
function filename_code(string $name):string{$code=pathinfo(basename($name),PATHINFO_FILENAME);return preg_replace('/[^A-Za-z0-9_-]/','',$code)?:'COLOR';}
